namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var result = new List<string>();
        int remaining = item.OnHand - item.Reserved;

        foreach (var zone in warehouse.Zones)
        {
            if (remaining <= 0)
                break;
            if (!CanAllocate(zone.Name, zone.Capacity))
                continue;

            int quantity = CalculateQuantity(remaining, zone.Capacity);
            if (quantity <= 0)
                continue;

            result.Add(FormatAllocation(zone.Name, quantity));
            remaining -= quantity;
        }

        AddOverflow(result, remaining);
        return result;
    }

    private static bool CanAllocate(string? zoneName, int capacity) =>
        capacity > 0 && !string.IsNullOrEmpty(zoneName);

    private static int CalculateQuantity(int remaining, int capacity)
    {
        if (remaining > capacity)
            return capacity;

        return remaining > capacity / 2 ? remaining - 1 : remaining;
    }

    private static string FormatAllocation(string zoneName, int quantity) =>
        $"{zoneName}:{quantity}";

    private static void AddOverflow(ICollection<string> result, int remaining)
    {
        if (remaining > 0)
            result.Add($"OVERFLOW:{remaining}");
    }
}
